      SeedCurriculum.module_data(
        "Integração de balanços e otimização de separações",
        "Compare alternativas de separação com balanços, recuperação, pureza e consumo energético.",
        "A seleção de uma operação não se resume ao nome do equipamento: é necessário definir vazões, composições, recuperações, pureza de produto, perdas admissíveis e restrições de energia e segurança. Um balanço por componente em regime estacionário sem reação estabelece que a soma das entradas é igual à soma das saídas. Recuperação do componente i é a fração do i alimentado que aparece na corrente de produto designada; pureza é sua fração na corrente. Uma alternativa pode ter alta recuperação e baixa pureza, ou o contrário.\n\nA integração de operações considera que correntes de uma etapa podem ser reciclos, purgas ou alimentação de outra. Reciclos acumulam impurezas se não houver purga; purgas reduzem acúmulo, mas perdem material. Balanços de energia permitem avaliar aquecimento, resfriamento e recuperação térmica; utilidades, capacidade, controle, emissões e tratamento de resíduos também entram na decisão. Uma comparação válida usa a mesma base de cálculo e fronteira de processo e explicita as hipóteses, em vez de otimizar uma unidade isolada.",
        "Uma alimentação contém 100 kg/h do componente A. A corrente de produto tem 40 kg/h de A em 80 kg/h totais. A recuperação de A é 40/100 = 40%, enquanto a pureza do produto é 40/80 = 50%. Relatar apenas uma dessas métricas ocultaria o compromisso entre separação e aproveitamento.",
        "Como se calcula a recuperação de um componente numa corrente de produto?",
        [ "Massa do componente no produto dividida pela massa total do produto.", "Massa do componente no produto dividida pela massa desse componente na alimentação.", "Vazão total de alimentação dividida pela temperatura.", "Massa de impureza no produto dividida pelo volume do equipamento." ],
        "b",
        "Recuperação compara quanto do componente alimentado foi recuperado na corrente escolhida; pureza, por sua vez, usa a massa total do produto.",
        [
          [ "Em uma alimentação há 50 kg/h de A e 30 kg/h são recuperados no produto. Qual é a recuperação?", [ "30%.", "50%.", "60%.", "80%." ], "c", "Recuperação = 30/50 × 100 = 60%." ],
          [ "Um produto contém 24 kg/h de A em 60 kg/h totais. Qual é a pureza mássica de A?", [ "24%.", "40%.", "60%.", "84%." ], "b", "Pureza = 24/60 × 100 = 40%." ],
          [ "Uma corrente de reciclo acumula uma impureza não consumida e não removida. Qual operação pode limitar o acúmulo?", [ "Purgar uma fração do reciclo.", "Fechar todas as saídas.", "Aumentar o reciclo sem limite.", "Ignorar o balanço do componente." ], "a", "Uma purga remove parte da impureza, embora também possa perder material valioso." ],
          [ "Por que a recuperação e a pureza devem ser especificadas separadamente?", [ "Porque medem aspectos diferentes do desempenho da separação.", "Porque são sempre numericamente iguais.", "Porque uma não usa balanço de massa.", "Porque pureza mede apenas energia." ], "a", "Recuperação se refere à fração alimentada recuperada; pureza expressa a composição do produto." ],
          [ "Uma alternativa eleva a pureza, mas reduz a recuperação e aumenta vapor. Qual abordagem é adequada?", [ "Comparar as métricas e custos dentro da mesma fronteira e requisitos.", "Escolher sempre a maior pureza.", "Ignorar consumo de utilidades.", "Somar percentuais incompatíveis." ], "a", "A decisão depende das especificações, perdas, energia e impacto econômico e ambiental." ],
          [ "Num balanço estacionário sem reação, sem acúmulo e com fronteira completa, a massa total:", [ "Pode ser criada pelo equipamento.", "Entrada total iguala saída total.", "Saída é sempre menor.", "Não pode ser contabilizada." ], "b", "A conservação de massa exige igualdade entre entrada e saída sob essas condições." ],
          [ "Qual é um risco de reciclo sem purga em um processo com contaminante inerte?", [ "Acúmulo progressivo do contaminante.", "Eliminação espontânea do contaminante.", "Redução obrigatória da concentração a zero.", "Aumento da massa molar do produto." ], "a", "Espécies não consumidas podem se acumular no circuito se não houver saída ou remoção." ],
          [ "Na integração térmica, recuperar calor de uma corrente quente pode:", [ "Reduzir demanda de utilidade, se temperaturas e operação forem compatíveis.", "Garantir consumo energético nulo.", "Alterar a conservação de energia.", "Dispensar controle de processo." ], "a", "A recuperação pode diminuir utilidades externas, limitada por força motriz, perdas e requisitos operacionais." ],
          [ "Para comparar dois fluxogramas, a base mais apropriada é:", [ "Bases de cálculo e fronteiras consistentes, com hipóteses explicitadas.", "Uma vazão para cada alternativa sem conversão.", "Apenas custo de compra do equipamento.", "Somente a cor do produto." ], "a", "A comparação só é significativa quando os limites, bases e critérios são equivalentes." ]
