          [ "Uma amostra diluída cinco vezes apresentou 3,0 mg/L no instrumento. Qual era a concentração antes da diluição?", [ "0,60 mg/L.", "3,0 mg/L.", "8,0 mg/L.", "15 mg/L." ], "d", "Multiplica-se a leitura pela razão de diluição: 3,0 × 5 = 15 mg/L." ],
          [ "Qual termo da expressão A = εbc representa o caminho óptico da cubeta?", [ "A.", "ε.", "b.", "c." ], "c", "O símbolo b representa o comprimento do caminho óptico." ],
          [ "Por que se mede um branco de reagentes?", [ "Para avaliar contribuições do solvente e reagentes ao sinal.", "Para substituir todos os padrões.", "Para provar ausência de qualquer interferência.", "Para alterar a concentração da amostra." ], "a", "O branco corrige ou monitora o sinal de fundo dos componentes sem analito." ],
          [ "Uma amostra está acima do maior padrão calibrado. Qual ação é apropriada?", [ "Extrapolar sem ressalvas.", "Diluir por fator conhecido e medir dentro da faixa validada.", "Reportar o máximo da curva.", "Zerar a absorbância manualmente." ], "b", "A extrapolação pode ser inválida; diluição controlada permite quantificação dentro da faixa." ],
          [ "Um R² muito próximo de 1 é suficiente para validar linearidade?", [ "Sim, em qualquer caso.", "Não; também se avaliam resíduos, faixa, padrões e desempenho.", "Sim, mesmo com padrões contaminados.", "Não se pode usar regressão." ], "b", "R² não revela sozinho curvatura, pontos influentes ou adequação do modelo." ],
          [ "Se a absorbância do branco é significativa e não foi corrigida, a concentração calculada por uma curva que assume intercepto zero tende a:", [ "Ser potencialmente enviesada.", "Ser necessariamente exata.", "Tornar-se independente do instrumento.", "Ser sempre zero." ], "a", "Sinal de fundo não tratado pode ser atribuído incorretamente ao analito." ],
          [ "Uma curva foi preparada em solvente puro, mas a matriz da amostra suprime a resposta. Qual estratégia pode ajudar?", [ "Avaliar adição de padrão ou calibração compatível com matriz.", "Ignorar a supressão.", "Usar apenas o R² da curva original.", "Aumentar casas decimais." ], "a", "Calibração em matriz ou adição de padrão pode compensar efeitos de matriz, se validada." ],
          [ "O limite de quantificação representa, em geral:", [ "A menor concentração que o método quantifica com desempenho definido.", "A concentração de todos os brancos.", "A maior concentração possível.", "A absorbância do solvente." ], "a", "O LOQ é associado à capacidade de quantificação com precisão e exatidão adequadas segundo critério." ],
          [ "Para uma absorbância constante, aumentar o caminho óptico b, sob a lei de Beer-Lambert e mesmas condições, tende a:", [ "Aumentar A proporcionalmente.", "Diminuir A a zero.", "Não alterar A.", "Trocar absorbância por massa." ], "a", "A é proporcional a b na faixa em que a lei é válida." ]
