        "b",
        "A resolução compara a separação entre picos com o alargamento das bandas.",
        [
          [ "Se tR = 6,0 min e tM = 1,0 min, qual o fator de retenção k'?", [ "0,20.", "5,0.", "6,0.", "7,0." ], "b", "k' = (6,0−1,0)/1,0 = 5,0." ],
          [ "Dois compostos têm k' praticamente iguais. Qual fator precisa mudar para aumentar sua distinção?", [ "Seletividade da interação com fases.", "Somente a resolução do relógio.", "A massa do frasco de coleta.", "A cor do pico." ], "a", "A seletividade expressa diferenças de retenção; ajustes de fase ou condições podem alterá-la." ],
          [ "Aumentar a eficiência da coluna tende principalmente a:", [ "Reduzir alargamento de pico, mantidas outras condições.", "Alterar a identidade química do analito.", "Eliminar a necessidade de calibração.", "Tornar todos os compostos igualmente retidos." ], "a", "Maior eficiência corresponde a bandas mais estreitas para uma mesma retenção." ],
          [ "Com largura de base 0,20 min para cada pico e separação entre máximos de 0,40 min, qual Rs pela fórmula 2Δt/(w1+w2)?", [ "0,5.", "1,0.", "2,0.", "4,0." ], "c", "Rs = 2 × 0,40/(0,20+0,20) = 2,0." ],
          [ "Por que tM é necessário para calcular k'?", [ "Porque remove a contribuição do tempo de passagem não retida.", "Porque mede diretamente a concentração.", "Porque substitui o padrão interno.", "Porque é a largura do pico." ], "a", "k' usa a retenção além do tempo de trânsito da fase móvel." ],
          [ "Um pico com mesmo tempo de retenção que um padrão garante identidade?", [ "Sim, sem exceções.", "Não; coeluição é possível e confirmação adicional pode ser necessária.", "Sim, desde que o cromatograma tenha cor.", "Não se pode usar padrões." ], "b", "Tempo de retenção isolado não exclui outros compostos com comportamento semelhante." ],
          [ "Em cromatografia líquida de fase reversa, aumentar a fração de solvente orgânico costuma, em muitos casos, reduzir retenção de compostos hidrofóbicos. Essa previsão:", [ "É uma tendência geral que depende do sistema e deve ser confirmada.", "É uma lei universal sem exceções.", "Significa que não há fase estacionária.", "Aplica-se apenas a gases." ], "a", "A força eluente do solvente pode reduzir retenção, mas o efeito depende de composição e analitos." ],
          [ "Um pico assimétrico e alargado pode comprometer:", [ "Integração e resolução.", "Somente a cor do frasco.", "A unidade de tempo morto.", "A massa molar do analito." ], "a", "Forma inadequada de pico dificulta integração e pode reduzir a separação observável." ],
          [ "Qual abordagem de quantificação reduz o impacto de variação de injeção, se apropriada ao método?", [ "Uso validado de padrão interno.", "Extrapolação de tempo de retenção.", "Remoção do branco.", "Troca de unidade após o cálculo." ], "a", "Um padrão interno acompanha preparação e injeção e pode compensar variações, desde que tenha comportamento adequado." ]
        ],
        level: "dificil"
