      SeedCurriculum.module_data(
        "Eletroanalítica e validação de métodos",
        "Relacione potencial, corrente e seletividade a controles, interferências e decisões de medição.",
        "Métodos eletroanalíticos medem propriedades elétricas relacionadas à composição: potenciometria observa potencial em condições de corrente desprezível; voltametria mede corrente em função de potencial aplicado; condutimetria mede capacidade de conduzir corrente. Na potenciometria, a equação de Nernst relaciona potencial à atividade iônica, não simplesmente à concentração. Em solução diluída e matriz controlada, atividade pode aproximar concentração, mas força iônica, temperatura, junção líquida e seletividade do eletrodo influenciam a resposta.\n\nA validação demonstra que o método atende ao uso pretendido, considerando seletividade, faixa, linearidade quando aplicável, precisão, exatidão/recuperação, limite de detecção e quantificação, robustez e incerteza. Interferentes podem produzir potencial ou corrente falsa; adição de padrão, eletrodos seletivos, separação ou máscara química podem mitigar problemas, desde que avaliados. Calibração precisa de padrões adequados, verificação independente e critérios de aceitação. Um instrumento não converte automaticamente sinal em verdade: a interpretação deve considerar princípio, matriz, controles e finalidade da decisão.",
        "Um eletrodo seletivo responde a um íon com inclinação observada de 56 mV por década a 25 °C, abaixo do comportamento ideal monovalente próximo de 59 mV/década em módulo. Antes de converter potencial em concentração, verifique calibração, temperatura, atividade, força iônica, inclinação e interferentes; não force a inclinação ideal no cálculo se a resposta medida indica desempenho diferente.",
        "Por que a atividade iônica é mais rigorosa que a concentração na interpretação de um eletrodo seletivo?",
        [ "Porque o potencial depende da atividade efetiva, influenciada por interações iônicas.", "Porque concentração não tem unidade.", "Porque atividade elimina a temperatura.", "Porque eletrodos medem massa diretamente." ],
        "a",
        "A equação de Nernst é formulada em termos de atividade; concentração é uma aproximação que depende das condições da solução.",
        [
          [ "Qual técnica mede potencial de eletrodo sob corrente praticamente nula?", [ "Potenciometria.", "Gravimetria.", "Turbidimetria.", "Filtração." ], "a", "Na potenciometria mede-se a diferença de potencial com corrente desprezível." ],
          [ "Um método apresenta boa repetibilidade, mas recuperação média de 70%. Como descrever o desempenho?", [ "Preciso, mas possivelmente enviesado ou com perda.", "Exato e sem viés.", "Sem qualquer informação.", "Seletivo por definição." ], "a", "Baixa dispersão pode coexistir com viés sistemático ou recuperação incompleta." ],
          [ "Qual controle verifica se a calibração continua adequada durante uma sequência?", [ "Padrão de verificação independente segundo critério.", "Apenas o primeiro padrão da curva.", "Um frasco vazio sem medida.", "A amostra mais concentrada sem preparo." ], "a", "Padrões de controle independentes ajudam a detectar deriva ou erro de calibração." ],
          [ "Em voltametria, a grandeza registrada em função do potencial aplicado é geralmente:", [ "Corrente.", "Massa molar.", "Volume de coluna.", "Densidade óptica exclusivamente." ], "a", "A resposta voltamétrica é corrente em função do potencial." ],
          [ "Um limite de detecção baixo garante quantificação precisa nesse mesmo nível?", [ "Sim.", "Não; detecção e quantificação têm critérios de desempenho diferentes.", "Sim, se a unidade for mg/L.", "Não existe diferença entre LD e LQ." ], "b", "O limite de quantificação exige desempenho quantitativo definido, geralmente superior ao mero sinal detectável." ],
          [ "A adição de padrão é especialmente útil quando:", [ "A matriz altera a resposta em relação aos padrões externos.", "A amostra não contém analito.", "Não existe instrumento.", "A curva precisa ser ocultada." ], "a", "A calibração por adição à própria matriz pode compensar efeitos de matriz, mediante pressupostos apropriados." ],
          [ "Se a inclinação de uma curva de eletrodo muda após uso prolongado, isso pode indicar:", [ "Alteração de desempenho que requer investigação ou recalibração.", "Aumento da massa do analito.", "Validade automática da calibração anterior.", "Que a temperatura não influencia a resposta." ], "a", "Mudança de inclinação é sinal de deriva ou degradação e afeta a conversão do potencial." ],
          [ "Qual característica representa a capacidade de medir o analito na presença de outras espécies?", [ "Seletividade.", "Resolução temporal.", "Volatilidade.", "Massa do eletrodo." ], "a", "Seletividade é a capacidade de distinguir a resposta do analito de interferentes." ],
          [ "Um método é robusto quando:", [ "Pequenas variações deliberadas em parâmetros não comprometem significativamente seu desempenho.", "Nunca requer calibração.", "Funciona sem procedimento.", "Produz sempre a mesma leitura para qualquer amostra." ], "a", "Robustez avalia a resistência do desempenho a pequenas variações operacionais previstas." ]
        ],
        level: "profissional"
      )
