    "tecnologia-quimica" => [
      SeedCurriculum.module_data(
        "Conversão, seletividade e balanço de reação",
        "Aplique estequiometria a conversão e seletividade em processos com reação química.",
        "Em um reator, os balanços de matéria incluem consumo e formação por reação. Conversão de um reagente A é a fração alimentada que reagiu: X_A = (n_A,entrada−n_A,saída)/n_A,entrada. Seletividade compara a formação do produto desejado com produtos concorrentes, e rendimento relaciona produto obtido à quantidade teórica ou ao reagente consumido, conforme definição explicitada. Conversão alta não implica necessariamente rendimento ou seletividade altos.\n\nA equação química precisa estar balanceada antes de calcular quantidades; coeficientes representam razões molares, não massas. Em processo contínuo, base temporal e fronteira devem ser consistentes. Reações paralelas, equilíbrio, reciclo, purga, excesso de reagente e limitações de transferência influenciam resultados. Relatar definições, base, unidades e composição evita comparações enganosas entre lotes ou tecnologias.",
        "Na reação A → P, alimentam-se 100 mol/h de A e saem 20 mol/h sem reagir. Conversão de A = (100−20)/100 = 80%. Se foram produzidos 60 mol/h de P, a seletividade molar para P relativa ao A consumido é 60/80 = 75% (com estequiometria 1:1 e sem outros termos relevantes).",
        "Se entram 200 mol/h de A e saem 50 mol/h de A sem reagir, qual é a conversão?",
        [ "25%.", "50%.", "75%.", "80%." ],
        "c",
        "X_A = (200−50)/200 × 100 = 75%.",
        [
          [ "Entram 80 kmol/h de A; 12 kmol/h saem sem reagir. Qual a conversão?", [ "15%.", "68%.", "80%.", "85%." ], "d", "Conversão = (80−12)/80 × 100 = 85%." ],
          [ "Por que conversão alta pode coexistir com baixo rendimento do produto desejado?", [ "Reações paralelas podem consumir reagente formando subprodutos.", "Conversão e rendimento são sempre sinônimos.", "O balanço deixa de valer.", "Produtos não podem ser quantificados." ], "a", "A conversão mede desaparecimento do reagente, não a parcela que formou o produto desejado." ],
          [ "Uma reação A + 2B → P consome 10 mol de A. Quantos mols de B são consumidos pela estequiometria?", [ "5 mol.", "10 mol.", "20 mol.", "30 mol." ], "c", "A razão B:A é 2:1, portanto 20 mol de B." ],
          [ "Em uma reação A → P com 40 mol de A consumidos e 30 mol de P formados, qual rendimento em base ao A consumido, com estequiometria 1:1?", [ "25%.", "50%.", "75%.", "133%." ], "c", "Rendimento = 30/40 × 100 = 75%." ],
          [ "Qual é o reagente limitante numa alimentação de 3 mol A e 4 mol B para A + 2B → P?", [ "A.", "B.", "Nenhum; proporção exata.", "P." ], "a", "Três mol A precisariam de seis mol B; há apenas quatro, então B é limitante." ],
          [ "Uma conversão calculada como 120% indica mais provavelmente:", [ "Erro de base, medição ou balanço, pois a definição usual não excede 100%.", "Desempenho excelente sem necessidade de revisão.", "Que massa foi criada.", "Que o produto é puro." ], "a", "A fração reagida de uma quantidade alimentada não deve exceder 1 sob a definição usual; investigue dados e base." ],
          [ "Qual informação precisa ser declarada ao comparar rendimentos de duas plantas?", [ "Definição e base do rendimento, além da fronteira e unidades.", "Apenas o nome do operador.", "Somente a cor do produto.", "A unidade de temperatura sem vazão." ], "a", "Rendimento pode ser definido em base alimentada, consumida, mássica ou molar; a base torna a comparação interpretável." ],
          [ "Num balanço contínuo de A, além das entradas e saídas, uma reação deve aparecer como:", [ "Termo de geração ou consumo por reação.", "Um termo de cor.", "Sempre zero, mesmo com reação.", "A massa do equipamento." ], "a", "Balanços reativos incluem geração/consumo conforme estequiometria e velocidade." ],
          [ "Se uma reação paralela consome A e forma subproduto, a seletividade para P tende a:", [ "Diminuir em comparação com o caso sem reação paralela.", "Ser igual à conversão por definição.", "Ser sempre maior que 100%.", "Não depender da distribuição de produtos." ], "a", "O reagente consumido que não forma P reduz a seletividade do produto desejado." ]
        ],
        level: "intermediario"
      ),
      SeedCurriculum.module_data(
        "Rendimento global e integração de reator-separação",
        "Avalie como reciclo, purga e recuperação pós-reação alteram o rendimento global.",
        "Uma tecnologia química combina transformação e separação. O rendimento global deve considerar não apenas o reator, mas também produto recuperado, perdas na separação, reciclo de reagente não convertido e purga necessária para controlar inertes ou subprodutos. Uma conversão por passagem baixa pode ser compatível com alto aproveitamento global se houver reciclo eficaz; em contrapartida, reciclo exige capacidade de bombeamento, separação e controle e pode acumular espécies indesejáveis.\n\nEm balanços de circuito, desenhe uma fronteira que inclua reator, separador, reciclo e purga. A corrente de reciclo é interna à fronteira global e não deve ser contada como alimentação externa; dentro de unidades individuais, aparece como entrada ou saída. Considere rendimento de recuperação, perdas, seletividade, equilíbrio, energia e segurança. A melhor condição depende de especificações e economia, não de maximizar uma variável isolada.",
        "Uma planta recebe 100 kg/h de reagente fresco. O reator converte 60% por passagem; o separador recupera 90% do produto formado. Se a estequiometria mássica útil for 1:1 e não houver outras perdas, o produto recuperado é 100 × 0,60 × 0,90 = 54 kg/h. O reagente não convertido que retorna em reciclo não deve ser somado novamente à alimentação fresca no balanço global.",
        "Qual fronteira evita contar repetidamente uma corrente de reciclo ao calcular consumo global de matéria-prima?",
        [ "Somente a linha de reciclo.", "A unidade reatora isolada, sem declarar as correntes.", "O circuito completo com alimentação fresca, produto, purga e perdas.", "Apenas o separador." ],
        "c",
        "Na fronteira global, reciclos são correntes internas; o balanço usa alimentação fresca e saídas externas.",
        [
          [ "Uma reação converte 50% por passagem e o reagente não convertido é reciclado sem perdas. O que pode ocorrer com a conversão global do reagente fresco?", [ "Ser maior que a conversão por passagem.", "Ser obrigatoriamente igual a zero.", "Ser sempre menor que 50%.", "Não pode ser definida." ], "a", "O reciclo permite que moléculas não reagidas retornem ao reator e reajam em passagens posteriores." ],
          [ "Se 80 kg/h de produto são formados e a recuperação do separador é 95%, quanto produto é recuperado?", [ "4 kg/h.", "76 kg/h.", "80 kg/h.", "84,2 kg/h." ], "b", "0,95 × 80 = 76 kg/h." ],
          [ "Por que uma purga pode ser necessária num circuito com inerte?", [ "Para evitar acúmulo de espécies que não reagem nem são separadas.", "Para aumentar a conversão por definição.", "Para eliminar a alimentação fresca.", "Para criar massa no sistema." ], "a", "A purga fornece uma saída para componentes que se acumulam no reciclo." ],
          [ "Uma purga maior tende a:", [ "Reduzir acúmulo, mas também pode aumentar perdas de reagente.", "Eliminar todos os custos sem impacto.", "Aumentar sempre o rendimento.", "Não afetar a composição do circuito." ], "a", "A purga controla inertes ao custo potencial de descarte e perda de materiais valiosos." ],
          [ "Em um balanço global, o reciclo interno deve ser:", [ "Somado como nova alimentação externa em cada passagem.", "Excluído das entradas e saídas externas, embora permaneça nos balanços unitários.", "Contado como produto.", "Ignorado também no balanço do reator." ], "b", "Correntes internas se cancelam na fronteira total, mas precisam ser consideradas em cada equipamento." ],
          [ "Uma recuperação de separação de 0,90 seguida de outra etapa de recuperação 0,80 resulta em recuperação combinada de:", [ "0,10.", "0,72.", "0,85.", "1,70." ], "b", "A fração recuperada sucessivamente é 0,90 × 0,80 = 0,72." ],
          [ "Aumentar reciclo sem verificar a capacidade do separador pode:", [ "Sobrecarregar unidades e elevar consumo e inventário.", "Garantir sempre pureza máxima.", "Remover o inerte automaticamente.", "Reduzir vazão interna." ], "a", "Mais reciclo eleva vazões internas e pode exceder capacidade e aumentar custos." ],
          [ "Qual indicador distingue produto formado de produto efetivamente recuperado?", [ "Rendimento do reator versus recuperação da separação.", "Somente temperatura ambiente.", "Número de equipamentos.", "Densidade do ar." ], "a", "O reator forma produto; perdas na separação fazem com que apenas uma fração seja recuperada." ],
          [ "Ao otimizar reciclo e purga, deve-se considerar:", [ "Conversão, acúmulo, perdas, energia, separação e segurança.", "Apenas a conversão de uma passagem.", "Somente a vazão de purga sem composição.", "Apenas o preço do reator." ], "a", "O ótimo global é um compromisso entre desempenho de reação e custos e riscos do circuito." ]
        ],
        level: "dificil"
      ),
      SeedCurriculum.module_data(
        "Escalonamento, variabilidade e qualidade de processo",
        "Planeje a passagem de bancada à escala produtiva sem extrapolar relações inadequadas.",
        "Escalonar um processo químico exige preservar fenômenos relevantes, não apenas multiplicar dimensões. Tempo de mistura, transferência de calor e massa, cinética, distribuição de residência, potência por volume e segurança podem mudar com a geometria e a escala. Um reator que remove calor com facilidade em bancada pode desenvolver pontos quentes em escala maior; isso afeta seletividade, qualidade, estabilidade e risco. Dados de piloto devem cobrir condições representativas, perturbações e operação de partida, regime e parada.\n\nA qualidade é construída por controles de matéria-prima, parâmetros críticos, amostragem e critérios de liberação. Ferramentas estatísticas distinguem variação comum de causas especiais, mas exigem dados confiáveis e processo suficientemente estável. Capacidade de processo não corrige processo fora de controle. Defina limites de operação seguros, alarmes, intertravamentos e plano de resposta a desvios; documente mudanças e avalie impacto sobre produto e ambiente. A decisão de escala integra produtividade, variabilidade, energia, manutenção e análise de risco.",
        "Em um tanque de bancada, o tempo de mistura é 20 s e a reação libera calor rapidamente. Se uma escala maior mantém a mesma velocidade de agitação por minuto, isso não garante o mesmo tempo de mistura nem remoção de calor. Antes de ampliar, compare potência por volume, geometria, coeficiente de transferência e perfil térmico em ensaio piloto, e defina limites de temperatura e resposta a falhas.",
        "Por que manter apenas a mesma rotação do agitador não garante comportamento equivalente em escala maior?",
        [ "Porque mistura e transferência dependem também de geometria, potência e escala.", "Porque rotação não tem unidade.", "Porque a massa não muda com a escala.", "Porque reações químicas param em tanques grandes." ],
        "a",
        "A rotação isolada não preserva necessariamente potência por volume, circulação, tempo de mistura nem transferência térmica.",
        [
          [ "Qual risco pode aumentar quando a geração de calor cresce mais rapidamente que a capacidade de remoção?", [ "Ponto quente e descontrole térmico.", "Redução automática de conversão.", "Desaparecimento da reação.", "Aumento da área por volume." ], "a", "A remoção de calor pode não acompanhar a geração, levando a elevação local de temperatura." ],
          [ "O tempo de residência médio de um reator contínuo é aproximadamente V/Q para volume útil V e vazão volumétrica Q. Se V=2,0 m³ e Q=0,50 m³/h, qual é o tempo?", [ "0,25 h.", "1,0 h.", "2,5 h.", "4,0 h." ], "d", "τ = V/Q = 2,0/0,50 = 4,0 h." ],
          [ "Qual dado de piloto é relevante para avaliar mistura?", [ "Tempo de mistura e distribuição de condições no tanque.", "Apenas massa do agitador.", "Cor do painel.", "Número de operadores." ], "a", "O tempo de mistura e a homogeneidade influenciam reação e qualidade." ],
          [ "Uma carta de controle apresenta causa especial. Antes de calcular capacidade do processo, deve-se:", [ "Investigar e estabilizar o processo.", "Ignorar pontos discrepantes.", "Redefinir especificações para incluir os dados.", "Aumentar produção." ], "a", "Capacidade é interpretável para processo estável; causas especiais devem ser investigadas." ],
          [ "Intertravamentos de segurança servem principalmente para:", [ "Colocar o processo em estado seguro diante de condições perigosas definidas.", "Substituir treinamento e manutenção.", "Aumentar a concentração do produto.", "Eliminar todos os riscos." ], "a", "Intertravamentos executam ações protetivas sob condições especificadas, mas não eliminam todo risco." ],
          [ "Um fator de processo crítico deve ser monitorado porque:", [ "Pode afetar atributos de qualidade ou segurança do produto.", "É sempre o mais barato.", "Não varia.", "Substitui análise de produto." ], "a", "Parâmetros críticos influenciam diretamente resultados importantes para qualidade e segurança." ],
          [ "Por que um processo fora de controle não deve ser avaliado apenas por Cp ou Cpk?", [ "Índices de capacidade pressupõem processo estável e dados representativos.", "Porque índices não usam dados.", "Porque especificações não existem.", "Porque média e dispersão são sempre nulas." ], "a", "A instabilidade torna estimativas de capacidade pouco confiáveis para prever desempenho futuro." ],
          [ "Ao alterar uma matéria-prima durante a ampliação, qual prática é indicada?", [ "Avaliar e documentar o impacto da mudança em processo, qualidade e segurança.", "Presumir equivalência pelo nome do fornecedor.", "Eliminar controles anteriores.", "Alterar limites sem revisão." ], "a", "Mudanças de insumo podem afetar composição e desempenho e requerem avaliação controlada." ],
          [ "Qual conjunto melhor representa decisão de escalonamento responsável?", [ "Produtividade, transferência, variabilidade, energia, riscos e qualidade.", "Somente volume do reator.", "Apenas velocidade de agitação.", "Cor e altura do tanque." ], "a", "Escalonar envolve fenômenos técnicos, qualidade, custos e segurança de todo o processo." ]
        ],
        level: "profissional"
      )
    ],
    "utilidades-efluentes" => [
      SeedCurriculum.module_data(
        "Balanço de vapor e retorno de condensado",
        "Quantifique consumo térmico e identifique por que recuperar condensado melhora a eficiência.",
        "Vapor fornece energia por condensação e pode atuar como utilidade de aquecimento. O consumo de vapor depende da carga térmica, do calor latente disponível nas condições de operação e de perdas. Um balanço simples para aquecer uma corrente sensível é Q = ṁ Cp ΔT; se houver mudança de fase, inclui-se calor latente. A pressão do vapor determina sua temperatura de saturação e entalpia, mas vapor superaquecido, condensado sub-resfriado e perdas exigem balanço de entalpia mais completo.\n\nO condensado ainda contém água tratada e energia sensível, por isso seu retorno reduz demanda de água de reposição e combustível, além de diminuir descarga. Purgadores removem condensado e gases não condensáveis sem desperdiçar vapor vivo quando operam corretamente; falhas abertas desperdiçam energia e falhas fechadas podem causar alagamento, golpe de aríete e perda de troca térmica. Isolamento, qualidade da água, controle de pressão e inspeção compõem a gestão da rede.",
        "Aquecem-se 1 000 kg/h de água de 20 °C a 80 °C, com Cp = 4,18 kJ/(kg·K). Q = 1 000 × 4,18 × 60 = 250 800 kJ/h, ou 69,7 kW. Se o vapor cede 2 100 kJ/kg ao condensar nas condições reais, o consumo ideal estimado é 250 800/2 100 = 119 kg/h; perdas exigem consumo maior.",
        "Para estimar vapor de aquecimento a partir de uma carga térmica, qual propriedade da corrente de vapor é necessária?",
        [ "A entalpia cedida por unidade de massa nas condições do processo.", "A cor do isolamento.", "A massa do purgador.", "A pressão atmosférica apenas, sem estado do vapor." ],
        "a",
        "O balanço usa a energia que cada quilograma de vapor pode transferir ao condensar e, se aplicável, resfriar.",
        [
          [ "Qual carga térmica aquece 100 kg/h de água com Cp=4,18 kJ/(kg·K) de 25 °C a 45 °C?", [ "836 kJ/h.", "4 180 kJ/h.", "8 360 kJ/h.", "83 600 kJ/h." ], "c", "Q = 100 × 4,18 × 20 = 8 360 kJ/h." ],
          [ "Se uma carga de 210 000 kJ/h é suprida por vapor que cede 2 100 kJ/kg, qual consumo ideal?", [ "10 kg/h.", "100 kg/h.", "210 kg/h.", "1 000 kg/h." ], "b", "ṁ = 210 000/2 100 = 100 kg/h." ],
          [ "Qual benefício do retorno de condensado é esperado?", [ "Recuperar água tratada e energia, reduzindo reposição e combustível.", "Aumentar descarga de água quente.", "Eliminar qualquer inspeção.", "Diminuir a pressão de todas as linhas a zero." ], "a", "Condensado conserva calor sensível e água previamente tratada." ],
          [ "Um purgador travado aberto pode provocar:", [ "Perda contínua de vapor vivo.", "Acúmulo de condensado no equipamento.", "Ausência de qualquer perda térmica.", "Aumento da pureza do produto." ], "a", "A falha aberta permite que vapor útil escape para a linha de retorno ou ambiente." ],
          [ "Um purgador travado fechado pode levar a:", [ "Alagamento da superfície de troca e piora da transferência de calor.", "Aumento de vapor disponível.", "Retorno total de energia sem risco.", "Vaporização instantânea de toda água." ], "a", "Sem remoção adequada, condensado acumula e reduz área efetiva de troca, além de riscos hidráulicos." ],
          [ "A carga sensível de aquecimento é proporcional a:", [ "Vazão mássica, calor específico e variação de temperatura.", "Somente volume do tanque.", "Pressão atmosférica ao quadrado.", "Cor do líquido." ], "a", "Q̇ = ṁCpΔT descreve a carga sensível sob propriedades aproximadamente constantes." ],
          [ "Por que a pressão do vapor deve ser considerada?", [ "Ela determina estado, temperatura de saturação e entalpia disponível.", "Ela não influencia propriedades.", "Para calcular massa molar da água.", "Porque altera a gravidade." ], "a", "As propriedades termodinâmicas do vapor dependem da pressão e do estado." ],
          [ "Qual conduta reduz perdas numa rede de vapor?", [ "Inspecionar purgadores e reparar isolamento degradado.", "Aumentar vazamentos para ventilar.", "Desativar retorno de condensado.", "Manter todas as válvulas parcialmente abertas." ], "a", "Purgadores e isolamento em boas condições limitam perdas de vapor e calor." ],
          [ "Se o balanço ideal calcula 119 kg/h e o consumo medido é 140 kg/h, qual explicação deve ser avaliada?", [ "Perdas térmicas, eficiência e hipóteses do cálculo.", "Que a massa foi criada.", "Que calor latente é irrelevante.", "Que o medidor necessariamente está certo." ], "a", "A diferença pode refletir perdas, condições diferentes, eficiência ou erro de medição." ]
        ],
        level: "intermediario"
      ),
      SeedCurriculum.module_data(
        "Água de resfriamento e ar comprimido",
        "Diagnostique carga térmica, aproximação de torre, secagem e perdas em utilidades.",
        "A água de resfriamento remove calor e normalmente circula por trocador e torre. Para uma corrente sem mudança de fase, Q̇ = ṁCpΔT. Em torre evaporativa, o resfriamento depende de evaporação e aproximação à temperatura de bulbo úmido; aproximação é a diferença entre temperatura da água fria e bulbo úmido, e não deve ser confundida com range, diferença entre água quente e fria. Concentração de sais, corrosão, incrustação e crescimento microbiológico exigem controle e tratamento compatíveis.\n\nAr comprimido tem custo elevado porque a compressão aquece o gás e perdas por vazamento mantêm compressores em operação. Condensação remove água, mas secadores e filtros devem atender ao ponto de orvalho e qualidade requerida no ponto de uso. Queda de pressão aumenta consumo e pode prejudicar instrumentos. Dimensione a utilidade pela demanda real, segregue usos que exigem qualidade diferente e verifique pressão, vazão, temperatura, qualidade e vazamentos antes de elevar setpoints.",
        "Um circuito de água remove 418 kW e a água aquece 5 K, com Cp = 4,18 kJ/(kg·K). Vazão mássica = 418 kJ/s ÷ (4,18 kJ/(kg·K) × 5 K) = 20 kg/s. Se a aproximação da torre piora, investigue bulbo úmido, vazão de ar, distribuição de água, incrustação e carga antes de aumentar indiscriminadamente a vazão.",
        "Numa torre, o que se chama aproximação?",
        [ "Diferença entre água quente e água fria.", "Diferença entre a água fria e a temperatura de bulbo úmido do ar.", "Temperatura do vapor no compressor.", "Queda de pressão no filtro." ],
        "b",
        "A aproximação mede o quão perto a água fria chega da temperatura de bulbo úmido; o range é água quente menos água fria.",
        [
          [ "Uma carga de 209 kW é removida com água que aquece 5 K; Cp=4,18 kJ/(kg·K). Qual vazão mássica aproximada?", [ "1,0 kg/s.", "10 kg/s.", "25 kg/s.", "100 kg/s." ], "b", "ṁ = 209/(4,18 × 5) = 10 kg/s." ],
          [ "O range de uma torre com água entrando a 35 °C e saindo a 29 °C é:", [ "3 °C.", "6 °C.", "29 °C.", "64 °C." ], "b", "Range = 35−29 = 6 °C." ],
          [ "A água fria sai da torre a 30 °C e o bulbo úmido é 25 °C. Qual a aproximação?", [ "5 °C.", "25 °C.", "30 °C.", "55 °C." ], "a", "Aproximação = 30−25 = 5 °C." ],
          [ "Um aumento de incrustação no trocador tende a:", [ "Adicionar resistência térmica e reduzir transferência.", "Elevar sempre o coeficiente global.", "Eliminar a necessidade de vazão.", "Alterar a composição do ar comprimido." ], "a", "Depósitos aumentam resistência térmica e podem reduzir desempenho." ],
          [ "Por que se controla a concentração de sais na água de torre?", [ "Para limitar incrustação, corrosão e purga excessiva.", "Para tornar a água potável automaticamente.", "Para eliminar evaporação.", "Para aumentar a pressão do ar." ], "a", "A evaporação concentra espécies; o controle químico e a purga limitam problemas operacionais." ],
          [ "Vazamentos de ar comprimido são dispendiosos porque:", [ "Compressores podem consumir energia para repor ar que não realiza trabalho útil.", "Ar não pode escapar de tubulações.", "Reduzem sempre a demanda elétrica.", "Aumentam a qualidade do ar." ], "a", "O sistema precisa manter pressão e vazão, consumindo energia para compensar perdas." ],
          [ "O ponto de orvalho sob pressão indica:", [ "Temperatura em que a água começa a condensar nas condições de pressão especificadas.", "A temperatura de ebulição do óleo.", "A pressão de descarga do compressor.", "A concentração de oxigênio." ], "a", "O ponto de orvalho caracteriza a umidade do ar comprimido e é referido a uma pressão." ],
          [ "Se instrumentos exigem ar seco e limpo, a escolha de secador deve considerar:", [ "Ponto de orvalho requerido, pressão e vazão.", "Somente o tamanho do compressor.", "A cor das mangueiras.", "A temperatura ambiente apenas." ], "a", "A especificação de qualidade depende de umidade, regime e demanda no ponto de uso." ],
          [ "Elevar o setpoint de pressão sem avaliar a rede pode:", [ "Aumentar consumo e vazamentos sem resolver restrições locais.", "Reduzir sempre o consumo.", "Diminuir a pressão de todas as áreas.", "Remover água do ar sem secador." ], "a", "Pressão maior pode elevar energia e perda por vazamento; primeiro diagnostique queda e demanda." ]
        ],
        level: "dificil"
      ),
      SeedCurriculum.module_data(
        "Tratamento de efluentes e conformidade operacional",
        "Construa decisões de tratamento com carga poluidora, eficiência, monitoramento e prevenção na origem.",
        "O tratamento de efluentes é uma sequência de barreiras escolhidas para características do afluente e requisitos de lançamento ou reúso. Pré-tratamento remove sólidos grosseiros e areia; processos físico-químicos podem equalizar, ajustar pH, coagular, flocular e separar sólidos; processos biológicos convertem matéria biodegradável em biomassa e produtos; etapas terciárias removem nutrientes, sais ou contaminantes específicos. A demanda bioquímica de oxigênio (DBO) e a demanda química de oxigênio (DQO) são indicadores distintos e não devem ser usados como sinônimos. Vazão e concentração juntas definem carga: L = Q × C, com conversão de unidades explícita.\n\nOperar com conformidade exige amostragem representativa, instrumentos verificados, registros de pH, vazão e outros parâmetros relevantes, manutenção, gestão de lodo e resposta a desvios. Uma eficiência percentual de remoção não garante atendimento se a concentração de entrada variar. Prevenção na fonte, segregação de correntes concentradas e reúso podem ser mais eficazes que diluir. A decisão deve considerar licenças e normas vigentes, risco ambiental, capacidade hidráulica e orgânica e destino de subprodutos; a instalação nunca deve substituir avaliação técnica e requisitos regulatórios locais.",
        "Uma estação recebe 500 m³/d de efluente com DQO de 400 mg/L. Carga afluente = 500 000 L/d × 400 mg/L = 200 000 000 mg/d = 200 kg/d. Com remoção de 90%, a carga removida é 180 kg/d e a carga remanescente é 20 kg/d; a concentração final só será 40 mg/L se a vazão permanecer aproximadamente igual e não houver outras entradas ou saídas relevantes.",
        "Para avaliar a carga diária de um poluente, quais duas medidas devem ser combinadas?",
        [ "Concentração e vazão.", "Cor e temperatura ambiente.", "Volume do tanque e idade da estação.", "pH e massa do operador." ],
        "a",
        "A carga é a quantidade por volume multiplicada pelo volume por tempo, com conversão adequada de unidades.",
        [
          [ "Uma corrente de 100 m³/d contém 200 mg/L de DQO. Qual carga aproximada?", [ "2 kg/d.", "20 kg/d.", "200 kg/d.", "2 000 kg/d." ], "b", "100 000 L/d × 200 mg/L = 20 000 000 mg/d = 20 kg/d." ],
          [ "Uma etapa remove 80% de uma carga de 50 kg/d. Qual carga resta?", [ "10 kg/d.", "20 kg/d.", "40 kg/d.", "50 kg/d." ], "a", "Carga remanescente = 50 × (1−0,80) = 10 kg/d." ],
          [ "Qual afirmação sobre DBO e DQO é correta?", [ "São indicadores distintos, relacionados a aspectos diferentes da matéria orgânica.", "São sempre numericamente iguais.", "Medem exclusivamente sólidos grosseiros.", "São unidades de vazão." ], "a", "DBO estima consumo biológico de oxigênio sob condições de ensaio; DQO usa oxidação química e os valores diferem." ],
